// Pega a mensagem do cliente, remove espaços e divide pela vírgula.
const itensSelecionados = $json.mensagem_cliente.replace(/\s/g, '').split(',');
const itensValidos = itensSelecionados.filter(item => item && !isNaN(parseInt(item)));

if (itensValidos.length === 0) {
  $json.mensagemResposta = "Por favor, envie uma lista\nde números válidos\nseparados por vírgula\n\n_*(Exemplo: 7, 9, 15)*_.";
  $json.sql = null;
} else {
  // Pega o mapa de IDs que agora contém os nomes dos itens
  const mapaId = JSON.parse($json.mapa_id_json);
  const primeiroItemNumero = itensValidos[0];

  // --- INÍCIO DA VERIFICAÇÃO ÚNICA ---
// 1. O código agora verifica a lista inteira de 'itensAProcessar'
let indicesValidos = true;
let itemInvalido = null;

for (const itemNum of itensValidos) {
if (!mapaId[itemNum]) {
// Se UM item da lista não for encontrado no mapa
indicesValidos = false;
itemInvalido = itemNum;
break; // Para o loop assim que encontrar o primeiro erro
}
}

$json.indicesValidos = indicesValidos; // Retorna true ou false

// 2. Se a lista inteira não for válida, interrompe tudo.
if (!indicesValidos) {
$json.mensagemResposta = `*⚠️ Atenção:* Algum *ITEM* escolhido\nnão existe no *CARDÁPIO*.\nPor favor, observe o cardápio novamente, e escolha os\nitens corretamente.\n\n----------------------------------------------------------\n\nPara escolher é muito simples,\nbasta enviar o *NÚMERO*\nreferente ao *ITEM*\nno *CARDÁPIO*.\n\n_Para *ADICIONAR MAIS*_\n_*DE UM* item, envie os_\n_números *SEPARADOS POR VÍRGULA*:_\n\n*(Exemplo: 5, 10, 3)*`;

$json.sql = `UPDATE conversas_bot SET estado_conversa = 'aguardando_escolha_item', itens_a_processar = NULL, expirando = FALSE, indice_item_atual = NULL, ultima_interacao = NOW() WHERE jid = '${$json.Jid}'`;
return $json; // Para a execução aqui.
}
// --- FIM DA VERIFICAÇÃO ÚNICA ---

  // ---- A MUDANÇA CRÍTICA ESTÁ AQUI ----
  const primeiroItemInfo = mapaId[primeiroItemNumero];
  const nomeDoPrimeiroItem = primeiroItemInfo ? primeiroItemInfo.nome : "Item Desconhecido";

// --- INÍCIO DA NOVA FUNÇÃO ---
// Pega o preço do item a partir do mapaId
  const precoNumerico = primeiroItemInfo ? primeiroItemInfo.preco : 0;
// Formata o preço para o padrão BRL (Ex: R$ 13,59)
  const precoDoPrimeiroItem = precoNumerico.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const estq = primeiroItemInfo ? primeiroItemInfo.estq : 0;
// --- FIM DA NOVA FUNÇÃO ---

  // Monta a nova pergunta, incluindo o nome do cliente e o nome do item
  const nomeCliente = $json.primeiro_nome;
  $json.mensagemResposta = `_*${nomeCliente}*_,\nadicionei os itens que\nvocê escolheu.😉\n\nQual a quantidade para o item:\n\n*${primeiroItemNumero})*`;
  if (nomeDoPrimeiroItem.toLowerCase().includes('combo')) {
    $json.mensagemResposta += ` 📦 ${nomeDoPrimeiroItem}\n\n_*Preço:*_ *${precoDoPrimeiroItem}*\n\n_*(Exemplo: 4)*_\n\u200B`;
  } else {
    $json.mensagemResposta += ` 🍫 ${nomeDoPrimeiroItem}\n\n_*Preço:*_ *${precoDoPrimeiroItem}*\n\n_*(Exemplo: 1)*_\n\u200B`;
  };

  // Prepara o SQL para salvar a lista e mudar o estado.
  $json.sql = `
    UPDATE conversas_bot
    SET
      estado_conversa = 'processando_lista_itens',
      itens_a_processar = '{${itensValidos.join(',')}}',
      indice_item_atual = 0,
      expirando = FALSE,
      ultima_interacao = NOW()
    WHERE jid = '${$json.Jid}'
  `;
}

return $json;

