const item = $input.first().json;
const estado = $items("Start")[0].json;

let etapas;

try {
  const limpo = item.property_etapas.replace(/[\u201C\u201D]/g,'"');
  etapas = JSON.parse(limpo);
} catch {
  return [{json:{erro:true,mensagemResposta:"Erro no combo"}}];
}

// Expande categorias automaticamente
const etapasFinal = [];

etapas.forEach(e=>{
  if(e.categorias){
    e.categorias.forEach(cat=>{
      etapasFinal.push({
        categoria: cat,
        regra: e.regra_especifica,
        escolhidos: []
      });
    });
  }else{
    etapasFinal.push({
      categoria: e.categoria,
      regra: e.regra_especifica,
      escolhidos: []
    });
  }
});

const combo = {
  id_combo: item.property_id,
  indice: item.property_ndice,
  nome: item.property_nome,
  preco: parseFloat(item.property_pre_o),
  qtd_necessaria: item.property_qtd_necessaria,
  etapaAtual: 0,
  etapas: etapasFinal,
  finalizados:[]
};

return [{
  json:{
    buscar_menu:true,
    proxima_categoria:etapasFinal[0].categoria,
    mensagemResposta:`Excelente escolha, *${estado.nome_cliente}*! 😋\n\nVocê escolheu o *${item.property_nome}*.\nVamos montá-lo:`,
    sql:`UPDATE conversas_bot
         SET combo_em_montagem='${JSON.stringify(combo)}'::jsonb,
             estado_conversa='montando_combo'
         WHERE jid='${estado.Jid}'`
  }
}];

// --- FORMATA CARDÁPIO + CRIA MAPA_ID_JSON ---

// itens vêm do node anterior (Notion / Buscar Cardápio)
const itensCardapio = $input.all().map(i => i.json);

// filtra apenas estoque disponível
const itensFiltrados = itensCardapio.filter(item =>
  parseInt(item.property_estoque, 10) > 0
);

// --- FORMATA TEXTO E CRIA MAPA ---
let menuTexto = "";
let mapaId = {};

for (const item of itensFiltrados) {

  const indice = item.property_ndice;
  if (!indice) continue;

  let linha = `*${indice})*\u200B`;

  if (item.property_em_promo) {
    linha += ` 🎁`;
  } else {
    linha += ` 🍫`;
  }

  linha += ` ${item.property_nome}`;

  if (item.property_medida) {
    linha += ` (${item.property_medida})`;
  }

  if (item.property_descri_o?.trim()) {
    linha += `\n\n_*Descrição:*_\n${item.property_descri_o.trim()}`;
  }

  menuTexto += linha + `\n\n`;

  // --- CRIA MAPA_ID_JSON ---
  const precoFinal =
    parseFloat(item.property_pre_o_promo) > 0
      ? parseFloat(item.property_pre_o_promo)
      : parseFloat(item.property_pre_o);

  mapaId[indice] = {
    id: item.property_id,
    nome: item.property_nome,
    preco: precoFinal,
    estq: item.property_estoque
  };
}

// fallback caso vazio
if (!menuTexto) {
  menuTexto = "🚫 Nenhum item disponível no momento.";
}

menuTexto += "ㅤ";

// retorno final
return [{
  json: {
    menu_formatado: menuTexto,
    mapa_id_json: JSON.stringify(mapaId)
  }
}];
